export function resolveLanguage(languages=[]){return /^zh\b/i.test(languages[0]||'')?'zh':'en';}
export let language='en';
export function setLanguage(value){language=value==='zh'?'zh':'en';}
export function t(key,values={}){return (messages[language][key]??key).replace(/\{(\w+)\}/g,(_,name)=>values[name]??'');}
export function applyTranslations(root=document){
  root.documentElement.lang=language==='zh'?'zh-CN':'en';root.title=t('pageTitle');
  for(const node of root.querySelectorAll('[data-i18n]'))node.textContent=t(node.dataset.i18n);
  for(const attr of ['aria-label','title','alt'])for(const node of root.querySelectorAll('[data-i18n-'+attr+']'))node.setAttribute(attr,t(node.getAttribute('data-i18n-'+attr)));
}
